sylvie: quick heads up 1: customer integration failed after we switched to the new invokeEnvelope shape. parser threw when arguments arrived as a string.
jamie: can you paste minimal payload?
sylvie: from support:
```json
{
  "invokeEnvelope": {
    "tool": "index_search",
    "arguments": "{\"q\":\"pricing api\"}",
    "meta": {"req": "z12"}
  }
}
```
marco: ugh double-encoded args. we should add a tiny \"defensive adapter\" example in structured-output.md and a one-liner note for SDKs.
rahul: i'll add a Go snippet for the partners repo; prefer json.RawMessage -> try-unmarshal pattern.
jamie: python adapter I suggest:
```py
import json

def safe_args(env):
    a = env.get('arguments')
    if isinstance(a, str):
        try:
            return json.loads(a)
        except json.JSONDecodeError:
            return {}
    return a or {}
```
marco: TS equivalent I'll add in PR:
```ts
export function normalize(resp: any) {
  const env = resp.invokeEnvelope ?? resp.tool_call ?? resp;
  let args = env?.arguments;
  if (typeof args === 'string') {
    try { args = JSON.parse(args); } catch { args = {}; }
  }
  return { ...env, arguments: args };
}
```
rahul: Go sketch:
```go
var raw json.RawMessage = env.Arguments
var out map[string]interface{}
if err := json.Unmarshal(raw, &out); err != nil {
  // try if raw is quoted JSON string
  var s string
  if err2 := json.Unmarshal(raw, &s); err2 == nil {
    json.Unmarshal([]byte(s), &out)
  }
}
```
